# 🟡 中风险：会修改集群/资源状态，执行前请确认目标、影响范围与授权
# 根据集群规模设置副本数
# 小集群（<50 节点）: 2 副本
# 中型集群（50-200 节点）: 3-5 副本
# 大型集群（>200 节点）: 按 100 节点 : 1 副本

# 设置反亲和性避免单点问题
kubectl patch deployment -n kube-system coredns -p '{
  "spec": {
    "replicas": 5,
    "template": {
      "spec": {
        "affinity": {
          "podAntiAffinity": {
            "requiredDuringSchedulingIgnoredDuringExecution": [{
              "labelSelector": {
                "matchLabels": {"k8s-app": "kube-dns"}
              },
              "topologyKey": "kubernetes.io/hostname"
            }]
          }
        }
      }
    }
  }
}'

# 资源配置参考
resources:
  requests:
    cpu: 200m      # 按 QPS 调整（1000 QPS ≈ 100m CPU）
    memory: 128Mi  # 缓存占用主要内存
  limits:
    cpu: 2000m     # 留足突发容量
    memory: 512Mi

.:53 {
    errors
    health {
       lameduck 5s  # 优雅关闭窗口
    }
    ready

    kubernetes cluster.local in-addr.arpa ip6.arpa {
       pods insecure
       fallthrough in-addr.arpa ip6.arpa
       ttl 30
    }

    prometheus :9153

    # 主配置：外部域名解析
    forward . 10.0.0.53 10.0.0.54 {  # 企业内网 DNS
       max_concurrent 1000
       policy sequential
       health_check 5s
    }

    # 高级配置：缓存策略
    cache 60 {
       success 9984 60   # 成功响应缓存 1 分钟
       denial 9984 10    # 否定响应缓存 10 秒
       prefetch 10 60s   # 预取机制
       serve_stale       # 上游失败时返回过期缓存
    }

    loop           # 环路检测
    reload         # 热加载
    loadbalance    # 多 IP 负载均衡
}

# 专用域转发（可选）
example.com:53 {
    errors
    cache 30
    forward . 192.168.1.10 192.168.1.11  # 特定域名专用 DNS
}

